    //             returnVal.stake[j] = memberHelpers.returnDepositAmount(validatorsList[i]);
    //             returnVal.choice[j] = uint256(validation.validatorChoice[validatorsList[i]]);
    //             returnVal.timeVal[j] = validation.validatorTime[validatorsList[i]];
    //             returnVal.url[j] = validation.validationUrl[validatorsList[i]];
    //             returnVal.validators[j] = validatorsList[i];
    //             returnVal.valHash[j] = validation.validationHash[validatorsList[i]];
    //             j++;
